async function piq(page,ctx){
  const tenantId=state.selectedTenantId;
  if(await renderProspectiqBridge(page,tenantId))return;
  const workflow=await loadWorkflow(tenantId); const data=workflow.data,target={profile:workflow.profile};
  if(state.selectedTenantId!==tenantId || state.route!=='piq')return;
  page.innerHTML=`<header data-piq-intro><div class="page-head"><div><h1>ProspectIQ</h1><p>Manage targeting profiles, discover prospects and assess fit, and review their intelligence.</p></div><button class="button secondary" id="v53-import-piq">Import List</button></div>
  <div class="v53-provider-banner"><strong>${workflow.collection.discovery_live?'Live Google Places':'Demonstration discovery'} · ${workflow.collection.research_live?'Live OpenAI Adaptive Research':'Demonstration research'}</strong></div></header>
  <div class="v53-prospect-grid">${data.opportunities.map(row=>`<article class="v53-prospect-card"><div class="v53-prospect-score"><strong>${row.score}</strong><span>match</span></div><div class="v53-grow"><div class="v53-row-head"><h3>${esc(row.company_name)}</h3><small>${esc(providerLabel(row))}</small>${pill(row.moved_to_crm?'In CRM':fitLabel(row),row.moved_to_crm?'green':statusTone(row.status))}</div><p>${esc(row.signal)}</p><div class="v53-prospect-stats"><span><b>${row.evidence_count}</b> evidence</span><span><b>${potentialLabel(row)}</b> potential</span><span data-piq-research-summary>${esc(row.research?.latest?researchMessage(row.research.latest):row.enhanced?'Research evidence recorded':row.research?.eligible?'Research eligible':row.research?.reason||'Research not yet run.')}</span></div></div><div class="v53-prospect-actions"><button class="button secondary small" data-open-piq="${row.id}">Open Intelligence</button>${(!row.enhanced||row.research?.eligible===true)?`<button class="button secondary small" data-research-piq="${row.id}">Run Adaptive Research</button>`:''}${row.moved_to_crm?`<button class="button small" data-v53-route="crm?tab=leads&source=ProspectIQ&search=${encodeURIComponent(row.company_name)}">Open in CRM</button>`:`<button class="button small" data-move-piq="${row.id}">Move to CRM</button>`}</div></article>`).join('')||empty('No prospects yet','Select a Target Profile and Pull Leads, or view historical results.')}</div>`;
  const pullButton=Object.assign(document.createElement('button'),{id:'v53-run-discovery',className:'button',textContent:'Pull Leads'});
  const controls=bindWorkflow(page,workflow,ctx,pullButton); applyResearchState(page,data.opportunities); if(controls.enabled) bindDiscovery({page,button:$('#v53-run-discovery'),...controls,tenantId,refresh:()=>ctx.navigate('piq'),demoMessage:result=>`${result.created.length} prospects discovered using ${result.provider_mode} mode`});
  restoreResearch(ctx,data.opportunities);
  $('#v53-import-piq').addEventListener('click',()=>simpleInfoModal('Import Prospect List','Use CSV import to preview, validate and commit prospect records. Live provider enhancement remains optional.'));
  $$('[data-open-piq]').forEach(btn=>btn.addEventListener('click',()=>openPiqDetail(btn.dataset.openPiq,ctx)));
  $$('[data-research-piq]').forEach(btn=>btn.addEventListener('click',async()=>{try{await startResearch(btn.dataset.researchPiq,ctx)}catch(e){toast(e.message,'error')}}));
  $$('[data-move-piq]').forEach(btn=>btn.addEventListener('click',async()=>{if(btn.disabled)return;btn.disabled=true;try{const result=await api(`/api/piq/${btn.dataset.movePiq}/move-to-crm`,{method:'POST',body:{}});toast(result.created?'Prospect moved to CRM with source attribution':'Prospect is already in CRM');ctx.navigate('piq')}catch(e){btn.disabled=false;toast(e.message,'error')}}));
}
